root=Path(sys.argv[1]); mode=sys.argv[2]; form=sys.argv[3]
assert Path(demiflow.__file__).resolve().is_relative_to(Path.cwd())
class Counter:
    def __init__(self): self.count=0
    def __call__(self, value):
        self.count+=1
